//! Five-channel search through the caller's ordinary scoped retrieval lane.

use serde::{Deserialize, Serialize};

use super::{Memory, MemoryError, MemoryResult, caps};
use crate::claim::{ClaimReadStatus, PointRead, ScopedReadResult};
use crate::store::{RetrievalBlendWeights, RetrievalScoreComponent};

/// Explicit channel inputs. Omitted channels do not run; vectors and phonetic
/// codes are supplied by the caller, not generated by an unconfigured model.
#[derive(Debug, Clone, Serialize, Deserialize, schemars::JsonSchema)]
#[serde(deny_unknown_fields)]
pub struct HybridSearchRequest {
    #[serde(default)]
    pub query: Option<String>,
    #[serde(default)]
    pub query_vector: Option<Vec<f32>>,
    #[serde(default)]
    pub phonetic_codes: Vec<String>,
    #[serde(default)]
    pub ppr: Option<HybridPprQuery>,
    #[serde(default)]
    pub temporal: Option<HybridTemporalQuery>,
    /// Pins scoring inputs for repeatable ranking on the same admitted corpus.
    /// This is not a historical read or a change to stored learned weights.
    #[serde(default)]
    pub replay: Option<HybridRankReplay>,
    pub limit: usize,
}

#[derive(Debug, Clone, Serialize, Deserialize, schemars::JsonSchema)]
#[serde(deny_unknown_fields)]
pub struct HybridPprQuery {
    /// Short record refs or 32-hex entity ids, admitted by the caller's lane.
    pub seeds: Vec<String>,
    pub depth: u32,
}

#[derive(Debug, Clone, Copy, Serialize, Deserialize, schemars::JsonSchema)]
#[serde(deny_unknown_fields)]
pub struct HybridTemporalQuery {
    pub start: u64,
    pub end: u64,
}

#[derive(Debug, Clone, Copy, Serialize, Deserialize, schemars::JsonSchema)]
#[serde(deny_unknown_fields)]
pub struct HybridRankReplay {
    /// Unix seconds for temporal interpretation and time-dependent scoring.
    pub now: u64,
    pub blend_weights: RetrievalBlendWeights,
}

/// Evidence for one admitted result, available even when telemetry is off.
#[derive(Debug, Clone, Serialize, Deserialize, schemars::JsonSchema)]
pub struct HybridSearchHit {
    pub entity_ref: String,
    pub source_revision_ref: Option<String>,
    pub score: f32,
    pub access_factor: Option<f32>,
    pub components: Vec<RetrievalScoreComponent>,
}

impl HybridSearchRequest {
    pub fn validate(&self) -> MemoryResult<()> {
        caps::check_limit_nonzero(self.limit)?;
        if let Some(query) = &self.query {
            caps::check_query(query)?;
        }
        if let Some(vector) = &self.query_vector {
            caps::check_dimensions(vector.len())?;
            if vector.iter().any(|value| !value.is_finite()) {
                return Err(MemoryError::bad_request("query_vector must be finite"));
            }
        }
        caps::check_batch_len("phonetic_codes", self.phonetic_codes.len())?;
        for code in &self.phonetic_codes {
            caps::check_query(code)?;
            if code.trim().is_empty() {
                return Err(MemoryError::bad_request("phonetic codes must not be empty"));
            }
        }
        if let Some(ppr) = &self.ppr {
            caps::check_batch_len("ppr.seeds", ppr.seeds.len())?;
            if ppr.seeds.is_empty() {
                return Err(MemoryError::bad_request("ppr requires seeds"));
            }
        }
        if let Some(time) = self.temporal {
            caps::check_as_of(Some(time.start))?;
            caps::check_as_of(Some(time.end))?;
        }
        if let Some(replay) = self.replay {
            caps::check_as_of(Some(replay.now))?;
            replay.blend_weights.normalized().map_err(|error| {
                MemoryError::bad_request(format!("replay.blend_weights: {error}"))
            })?;
        }
        if self
            .query
            .as_ref()
            .is_none_or(|query| query.trim().is_empty())
            && self.query_vector.is_none()
            && self.phonetic_codes.is_empty()
            && self.ppr.is_none()
            && self.temporal.is_none()
        {
            return Err(MemoryError::bad_request("hybrid search requires a channel"));
        }
        Ok(())
    }
}

impl Memory<'_> {
    /// Runs the existing retrieval pipeline with explicit channels and returns
    /// only the evidence for hits the fresh terminal read still admits.
    pub fn query_hybrid(
        &self,
        input: &HybridSearchRequest,
    ) -> MemoryResult<ScopedReadResult<Vec<HybridSearchHit>>> {
        input.validate()?;
        let (limit, _) = caps::clamp_search_limit(input.limit);
        let lane = self.read_lane(ClaimReadStatus::Surfaceable)?;
        let mut receipt = lane.read_receipt(None, 0)?;
        let mut seeds = Vec::new();
        if let Some(ppr) = &input.ppr {
            let reads = ppr
                .seeds
                .iter()
                .map(|reference| {
                    self.resolve_ref_in_lane(&lane, reference)
                        .map(PointRead::id)
                })
                .collect::<MemoryResult<Vec<_>>>()?;
            let admitted = lane.read(&reads, None)?;
            receipt.restrict_with(&admitted.receipt);
            seeds.extend(admitted.value.into_iter().flatten().map(|row| row.id));
        }
        self.produced_from(seeds.iter().copied());
        let (filter, policy) = lane.recall_plan()?;
        let admitted =
            |_: &crate::store::StoreRead<'_>, txn: &heed::RoTxn<'_>, id: &crate::EntityId| {
                lane.recall_candidate_in(txn, &policy, &filter, id)
            };
        let mut pipeline = self
            .vault
            .query()
            .reading(lane.store_read())
            .authority_filter(filter.clone())
            .scoped_note_reader(lane.actor_key().clone())
            .caller_off_device(lane.off_device())
            .filter_candidates(&admitted)
            .boost_recency(crate::pipeline::DEFAULT_RECENCY_HALF_LIFE_DAYS)
            .boost_salience()
            .boost_confidence()
            .boost_gravity()
            .limit(limit);
        if let Some(query) = &input.query {
            pipeline = pipeline.search_text(query, limit);
        }
        if let Some(vector) = &input.query_vector {
            pipeline = pipeline.search_vector(vector, limit);
        }
        if !input.phonetic_codes.is_empty() {
            let codes = input
                .phonetic_codes
                .iter()
                .map(String::as_str)
                .collect::<Vec<_>>();
            pipeline = pipeline.search_phonetic(&codes);
        }
        if let Some(ppr) = &input.ppr {
            pipeline = pipeline.search_ppr(&seeds, ppr.depth);
        }
        if let Some(time) = input.temporal {
            pipeline = pipeline.search_temporal(time.start, time.end, limit);
        }
        if let Some(replay) = input.replay {
            pipeline = pipeline
                .with_temporal_now(replay.now)
                .with_blend_weights(replay.blend_weights)?;
        }
        let output = pipeline.run_for_pack()?;
        lane.end_recall_plan()?;
        let mut results = lane.filter_search_results(
            output.scores,
            limit,
            None,
            &filter,
            &policy,
            output.read_suppressed,
            &output.revisions,
        )?;
        results.receipt.restrict_with(&receipt);
        self.produced_from(results.value.iter().map(|hit| hit.id));
        Ok(results.map(|hits| {
            hits.into_iter()
                .map(|hit| {
                    let evidence = output
                        .score_breakdown
                        .iter()
                        .find(|evidence| &evidence.result_id == hit.id.as_bytes());
                    HybridSearchHit {
                        entity_ref: hit.id.to_hex(),
                        source_revision_ref: output
                            .revisions
                            .get(&hit.id)
                            .map(|revision| revision.to_hex()),
                        score: hit.score,
                        access_factor: evidence.and_then(|evidence| evidence.access_factor),
                        components: evidence
                            .map(|evidence| evidence.components.clone())
                            .unwrap_or_default(),
                    }
                })
                .collect()
        }))
    }
}
